// Filter appointments needing reminders
const config = $('Set Config').first().json.config;
const appointments = $input.all().map(item => item.json);
const now = new Date();

// Calculate time windows for reminders
// 24h reminder: appointments between 23h and 27h from now
// 2h reminder: appointments between 1h30m and 3h30m from now
const reminder24hMinMs = 23 * 60 * 60 * 1000; // 23 hours
const reminder24hMaxMs = 27 * 60 * 60 * 1000; // 27 hours
const reminder2hMinMs = 1.5 * 60 * 60 * 1000;  // 1.5 hours
const reminder2hMaxMs = 3.5 * 60 * 60 * 1000;  // 3.5 hours

const remindersToSend = [];

for (const apt of appointments) {
  const startTime = new Date(apt.start_time);
  const timeUntilMs = startTime - now;

  // Skip past appointments
  if (timeUntilMs < 0) continue;

  // Check 24h reminder
  const needs24h = apt.reminder_24h_sent !== 'true' && 
                   apt.reminder_24h_sent !== true &&
                   timeUntilMs >= reminder24hMinMs && 
                   timeUntilMs <= reminder24hMaxMs;

  // Check 2h reminder
  const needs2h = apt.reminder_2h_sent !== 'true' && 
                  apt.reminder_2h_sent !== true &&
                  timeUntilMs >= reminder2hMinMs && 
                  timeUntilMs <= reminder2hMaxMs;

  if (needs24h) {
    remindersToSend.push({
      ...apt,
      reminderType: '24h',
      reminderColumn: 'reminder_24h_sent',
      config
    });
  }

  if (needs2h) {
    remindersToSend.push({
      ...apt,
      reminderType: '2h',
      reminderColumn: 'reminder_2h_sent',
      config
    });
  }
}

if (remindersToSend.length === 0) {
  return { json: { noReminders: true, message: 'No reminders to send at this time' } };
}

return remindersToSend.map(r => ({ json: r }));

// Check quiet hours and adjust send time if needed
const item = $input.first().json;
const config = item.config;
const now = new Date();

// Parse quiet hours
const [quietStartHour, quietStartMin] = (config.quietHoursStart || '20:00').split(':').map(Number);
const [quietEndHour, quietEndMin] = (config.quietHoursEnd || '08:00').split(':').map(Number);

// Get current hour in the configured timezone
// For simplicity, we'll use UTC offset calculation
const currentHour = now.getHours();
const currentMin = now.getMinutes();

// Check if current time is in quiet hours
// Quiet hours span overnight (e.g., 20:00 to 08:00)
let inQuietHours = false;

if (quietStartHour > quietEndHour) {
  // Overnight quiet hours (e.g., 20:00 - 08:00)
  inQuietHours = currentHour >= quietStartHour || currentHour < quietEndHour ||
                 (currentHour === quietEndHour && currentMin < quietEndMin);
} else {
  // Same day quiet hours (e.g., 22:00 - 23:00)
  inQuietHours = (currentHour > quietStartHour || (currentHour === quietStartHour && currentMin >= quietStartMin)) &&
                 (currentHour < quietEndHour || (currentHour === quietEndHour && currentMin < quietEndMin));
}

if (inQuietHours) {
  // We're in quiet hours - skip this reminder for now
  // It will be picked up when quiet hours end
  return {
    json: {
      ...item,
      skipForQuietHours: true,
      message: 'Skipping reminder due to quiet hours. Will send after ' + config.quietHoursEnd
    }
  };
}

return {
  json: {
    ...item,
    skipForQuietHours: false
  }
};
